  const { Items = [] } = await MODELO_PROGRAMA.build(EntityRepository).query(
    { index: 'PorEmisora', partition: emisoraId },
    { filters: { Programa: { attr: 'duracionMinutos', gte: minimo } } }
  );
  return Items;
}
